"""Host control-flow tests plus strict Mach-O relocation failure cases."""
import json
import hashlib
from pathlib import Path
import shutil
import struct
import subprocess
import sys
import tempfile
import unittest
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from storage_boot_hook import redirect_object as redirect_bsd_object, verify_chain, baseline_call, ORIGINAL, WRAPPER
from build_ufs_dormant import macho


def redirect_object(raw):
    return redirect_bsd_object(raw, dict(call_offset=0, function_size=8))


def object_bytes(local_label=False, tail_call=False, dynamic=False):
    entries = [('_bsd_init', 0xf, 1, 0)]
    if local_label: entries.append(('ltmp_inside_function', 0xe, 1, 4))
    if tail_call: entries.append(('_bsd_autoconf', 0xf, 1, 8))
    entries.append((ORIGINAL, 1, 0, 0))
    strings, symbols = b'\0', b''
    for name, kind, section, value in entries:
        symbols += struct.pack('<IBBHQ', len(strings), kind, section, 0, value)
        strings += name.encode() + b'\0'
    target = len(entries) - 1
    words = [0x94000000, 0xd65f03c0] + ([0x14000000, 0xd503201f] if tail_call else [])
    code_bytes = struct.pack('<'+'I'*len(words), *words)
    # Clang orders the later tail relocation before the inlined BL relocation.
    relocations = ([struct.pack('<2I', 8, 0x2d000000 | target)] if tail_call else [])
    relocations += [struct.pack('<2I', 0, 0x2d000000 | target)]
    rel_bytes = b''.join(relocations)
    commands = 152 + 24 + (80 if dynamic else 0)
    code = 32 + commands
    rel = code + len(code_bytes)
    sym = rel + len(rel_bytes)
    st = sym + len(symbols)
    head = struct.pack('<8I', 0xfeedfacf, 0x100000c, 2, 1, 3 if dynamic else 2, commands, 0, 0)
    seg = struct.pack('<II16s4Q4I', 0x19, 152, b'', 0, len(code_bytes), code, len(code_bytes), 7, 7, 1, 0)
    sec = struct.pack('<16s16sQQ8I', b'__text', b'__TEXT', 0, len(code_bytes), code, 2, rel, len(relocations), 0x80000400, 0, 0, 0)
    tab = struct.pack('<6I', 2, 24, sym, len(entries), st, len(strings))
    dysym = struct.pack('<20I', 0xb, 80, 0, 0, 0, target, target, 1, *([0]*12)) if dynamic else b''
    return bytearray(head + seg + sec + tab + dysym + code_bytes + rel_bytes + symbols + strings)


class HookObjectTests(unittest.TestCase):
    def test_local_label_inside_bsd_does_not_shorten_function(self):
        raw = object_bytes(local_label=True)
        struct.pack_into('<2I', raw, 208, 0xd503201f, 0x94000000)
        struct.pack_into('<I', raw, 216, 4)
        # The old nearest-symbol check wrongly treated this label as the end.
        info = macho(raw, 1)
        self.assertEqual(info['defined']['ltmp_inside_function'], 4)
        result, report = redirect_bsd_object(raw, dict(call_offset=4, function_size=8))
        self.assertEqual(result[208:216], raw[208:216])
        self.assertEqual(report['baseline']['call_offset'], 4)

    def test_mismatched_baseline_offset_and_extent_are_rejected(self):
        for contract in (dict(call_offset=4, function_size=8), dict(call_offset=0, function_size=0)):
            with self.subTest(contract=contract), self.assertRaises(ValueError):
                redirect_bsd_object(object_bytes(), contract)

    def test_exact_site_redirect_preserves_code_and_original_symbols(self):
        raw = object_bytes()
        changed, report = redirect_object(raw)
        self.assertEqual(changed[208:216], raw[208:216])
        self.assertEqual(changed[224:256], raw[224:256])
        self.assertEqual(changed[272:272+len(raw)-256], raw[256:])
        self.assertEqual(macho(changed, 1)['undefined'], {ORIGINAL, WRAPPER})
        self.assertEqual(report['selected_relocations_changed'], 1)
        allowed = set(range(196, 208)) | set(range(220, 224))
        self.assertTrue(all(i in allowed for i, (a,b) in enumerate(zip(raw[:256],changed[:256])) if a != b))

    def test_preserves_non_inlined_tail_call_and_dynamic_symbol_groups(self):
        for dynamic in (False, True):
            raw = object_bytes(tail_call=True, dynamic=dynamic)
            changed, report = redirect_object(raw)
            code = 288 if dynamic else 208
            rel = code + 16
            self.assertEqual(changed[code:rel+8], raw[code:rel+8])
            self.assertEqual(struct.unpack_from('<I', changed, rel+12)[0], 0x2d000003)
            self.assertEqual(report['other_original_import_relocations_preserved'], 1)
            self.assertEqual(macho(changed,1)['undefined'], {ORIGINAL, WRAPPER})
            if dynamic:
                self.assertEqual(struct.unpack_from('<2I',changed,232), (2,2))

    def test_reject_wrong_relocation_shape(self):
        for bits in (0x2c000001, 0x0d000001, 0x29000001):
            raw = object_bytes(); struct.pack_into('<I', raw, 220, bits)
            with self.subTest(bits=bits), self.assertRaises(ValueError): redirect_object(raw)

    def test_reject_non_call(self):
        raw = object_bytes(); struct.pack_into('<I', raw, 208, 0x14000000)
        with self.assertRaises(ValueError): redirect_object(raw)

    def test_reject_relocation_outside_text(self):
        raw = object_bytes(); struct.pack_into('<I', raw, 216, 8)
        with self.assertRaises(ValueError): redirect_object(raw)

    def test_reject_non_bsd_owner(self):
        raw = object_bytes(); raw[257:266] = b'_bad_init'
        with self.assertRaises(ValueError): redirect_object(raw)

    def test_reject_truncated_and_extra_extent(self):
        for raw in (object_bytes()[:-1], object_bytes() + b'x'):
            with self.assertRaises(ValueError): redirect_object(raw)

    def test_reject_second_application(self):
        raw, _ = redirect_object(object_bytes())
        with self.assertRaises(ValueError): redirect_object(raw)


class BootFlowTests(unittest.TestCase):
    def test_actual_boot_source_control_flow(self):
        compiler = shutil.which('c++') or shutil.which('g++') or shutil.which('clang++')
        self.assertIsNotNone(compiler, 'A host C++ compiler is required')
        source = Path(__file__).resolve().parents[1]/'MyronStorageBoot.cpp'
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            (root/'IOKit').mkdir(); (root/'pexpert').mkdir()
            (root/'IOKit/IOLib.h').write_text('#pragma once\nconstexpr int kIOReturnNotReady=-1;\nvoid IOLog(const char*,...);\n')
            (root/'pexpert/pexpert.h').write_text('#pragma once\n#include <cstddef>\nbool PE_parse_boot_argn(const char*,void*,int);\n')
            test = r'''
#include <cassert>
#include <cstdlib>
#include <cstring>
#include <vector>
SOURCE
static int scenario, original_result, registration_result;
static unsigned requested;
static bool present;
static std::vector<int> events;
extern "C" int IOKitBSDInit(){events.push_back(1);return original_result;}
bool PE_parse_boot_argn(const char *name,void *out,int size){
 assert(!strcmp(name,"myron27-storage") && size==sizeof(unsigned));
 events.push_back(2);*static_cast<unsigned*>(out)=requested;return present;
}
extern "C" int myron_ufs_register_classes(){
 events.push_back(3);
 if(scenario==8) assert(myron_storage_iokit_bsd_init()==0);
 return registration_result;
}
extern "C" void myron_ufs_probe(){events.push_back(4);}
void IOLog(const char*,...){}
int main(int argc,char **argv){
 assert(argc==2);scenario=atoi(argv[1]);present=true;requested=2;
 if(scenario==0)present=false;
 if(scenario==1)requested=0;
 if(scenario==2)requested=3;
 if(scenario==3)original_result=-7;
 if(scenario==4)requested=1;
 if(scenario==5)registration_result=-8;
 if(scenario==9)requested=~0U;
 assert(myron_storage_iokit_bsd_init()==original_result);
 std::vector<int> expected;
 if(scenario==3)expected={1};
 else if(scenario==0||scenario==1||scenario==2||scenario==9)expected={1,2};
 else if(scenario==4||scenario==5)expected={1,2,3};
 else if(scenario==8)expected={1,2,3,1,2,4};
 else expected={1,2,3,4};
 assert(events==expected);
 if(scenario==7){assert(myron_storage_iokit_bsd_init()==0);expected.push_back(1);expected.push_back(2);assert(events==expected);}
 assert(myron_storage_boot_stage==(scenario==5?2:scenario==4?3:(scenario==6||scenario==7||scenario==8)?5:0));
 if(scenario==5)assert(myron_storage_boot_status==-8);
}
'''.replace('SOURCE', '#include '+json.dumps(str(source)))
            (root/'test.cpp').write_text(test)
            subprocess.run([compiler, '-std=c++17', '-Wall', '-Wextra', '-Werror', '-I', str(root),
                            str(root/'test.cpp'), '-o', str(root/'test')], check=True)
            for scenario in range(10):
                with self.subTest(scenario=scenario):
                    subprocess.run([str(root/'test'), str(scenario)], check=True)


class LinkedChainTests(unittest.TestCase):
    @staticmethod
    def kernel(base=0x1000):
        names = ['_bsd_init', WRAPPER, ORIGINAL, '_myron_ufs_register_classes', '_myron_ufs_probe']
        offsets = [0, 8, 24, 32, 40]
        strings = b'\0'; symbols = b''
        for name, off in zip(names, offsets):
            symbols += struct.pack('<IBBHQ', len(strings), 0xf, 1, 0, base + 224 + off)
            strings += name.encode() + b'\0'
        words = [0x94000002, 0xd65f03c0, 0x94000004, 0x94000005,
                 0x94000006, 0xd65f03c0] + [0xd65f03c0, 0xd503201f] * 3
        function_starts = bytes([0xe0, 1, 8, 16, 8, 8, 0])
        function_offset = 224 + 48 + len(symbols) + len(strings)
        extent = function_offset + len(function_starts)
        head = struct.pack('<8I', 0xfeedfacf, 0x100000c, 2, 2, 3, 192, 0, 0)
        seg = struct.pack('<II16s4Q4I', 0x19, 152, b'__TEXT', base, extent, 0, extent, 7, 5, 1, 0)
        sec = struct.pack('<16s16sQQ8I', b'__text', b'__TEXT', base+224, 48, 224, 2, 0, 0, 0x80000400, 0, 0, 0)
        tab = struct.pack('<6I', 2, 24, 272, 5, 352, len(strings))
        starts = struct.pack('<4I', 0x26, 16, function_offset, len(function_starts))
        return bytearray(head+seg+sec+tab+starts+struct.pack('<12I', *words)+symbols+strings+function_starts)

    def setUp(self):
        # Available in the repository's build layout and local validation layout.
        here = Path(__file__).resolve()
        self.tool = next((p/'kits/XnuPrelink' for p in [*here.parents]
                          if (p/'kits/XnuPrelink/kc_image.py').is_file()), None)
        if self.tool is None:
            self.tool = next((p/'upstream/kits/XnuPrelink' for p in here.parents
                              if (p/'upstream/kits/XnuPrelink/kc_image.py').is_file()), None)
        self.assertIsNotNone(self.tool, 'Pinned XnuPrelink is required')

    def test_linked_and_relocated_edges(self):
        with tempfile.TemporaryDirectory() as tmp:
            native, final = Path(tmp)/'native', Path(tmp)/'final'
            native.write_bytes(self.kernel()); final.write_bytes(self.kernel(0x9000))
            report = dict(candidate_sha256=hashlib.sha256(final.read_bytes()).hexdigest(),
                          inputs=dict(native_sha256=hashlib.sha256(native.read_bytes()).hexdigest()),
                          statistics=dict(segment_layout={'text':dict(old='0x1000', new='0x9000', size='0x1000')}))
            final.with_suffix('.json').write_text(json.dumps(report))
            self.assertEqual(len(verify_chain(native, self.tool)['edges']), 4)
            self.assertEqual(len(verify_chain(native, self.tool, final)['edges']), 4)
            report['candidate_sha256'] = '0'*64
            final.with_suffix('.json').write_text(json.dumps(report))
            with self.assertRaisesRegex(ValueError, 'Stale'): verify_chain(native, self.tool, final)

    def test_missing_probe_edge_and_bypassed_wrapper_rejected(self):
        for offset, instruction in ((240, 0xd503201f), (224, 0x94000006)):
            with self.subTest(offset=offset), tempfile.TemporaryDirectory() as tmp:
                path = Path(tmp)/'native'; raw = self.kernel()
                struct.pack_into('<I', raw, offset, instruction); path.write_bytes(raw)
                with self.assertRaises(ValueError): verify_chain(path, self.tool)

    def test_baseline_call_uses_function_starts(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp)/'native'; raw = self.kernel()
            struct.pack_into('<I', raw, 224, 0x94000006)
            path.write_bytes(raw)
            result = baseline_call(path, self.tool)
            self.assertEqual(result['call_offset'], 0)
            self.assertEqual(result['function_size'], 8)
            struct.pack_into('<I', raw, 224, 0xd503201f); path.write_bytes(raw)
            with self.assertRaisesRegex(ValueError, 'unique'): baseline_call(path, self.tool)


if __name__ == '__main__': unittest.main()

