    if (EFI_ERROR (Status)) { return Status; }
    IsKernel = (NameEnd - Name == sizeof ("com.apple.kernel") - 1) &&
               (CompareMem (Root + Offset + Name, "com.apple.kernel", sizeof ("com.apple.kernel")) == 0);
    Status = EFI_LOAD_ERROR;
