}

STATIC
EFI_STATUS
OpenKernel (EFI_FILE_PROTOCOL *Root, CONST CHAR16 *Path, EFI_FILE_PROTOCOL **FileOut,
            UINTN *FileSize, KERNEL *Kernel)
{
  EFI_FILE_PROTOCOL *File;
  EFI_FILE_INFO *Info;
  EFI_STATUS Status;
  UINTN InfoSize;
  UINTN InfoCapacity;
  UINTN HeaderSize;
  UINT8 *Header;
  *FileOut = NULL;
  *FileSize = 0;
  Info = NULL;
  Header = NULL;
  Status = Root->Open (Root, &File, (CHAR16 *)Path, EFI_FILE_MODE_READ, 0);
  if (EFI_ERROR (Status)) { return Status; }
  InfoSize = 0;
  Status = File->GetInfo (File, &gEfiFileInfoGuid, &InfoSize, NULL);
  if ((Status != EFI_BUFFER_TOO_SMALL) || (InfoSize < SIZE_OF_EFI_FILE_INFO) || (InfoSize > SIZE_64KB)) {
    if (!EFI_ERROR (Status) || (Status == EFI_BUFFER_TOO_SMALL)) { Status = EFI_COMPROMISED_DATA; }
    goto Done;
  }
  InfoCapacity = InfoSize;
  Info = AllocatePool (InfoCapacity);
  if (Info == NULL) { Status = EFI_OUT_OF_RESOURCES; goto Done; }
  Status = File->GetInfo (File, &gEfiFileInfoGuid, &InfoSize, Info);
  if (EFI_ERROR (Status)) { goto Done; }
  if ((InfoSize < SIZE_OF_EFI_FILE_INFO) || (InfoSize > InfoCapacity) ||
      (Info->Size < SIZE_OF_EFI_FILE_INFO) || (Info->Size > InfoSize) ||
      (Info->Attribute & EFI_FILE_DIRECTORY) || (Info->FileSize < 32) || (Info->FileSize > SIZE_128MB)) {
    Status = EFI_BAD_BUFFER_SIZE; goto Done;
  }
  *FileSize = (UINTN)Info->FileSize;
  Status = ReadKernelHeaderAt (File, *FileSize, 0, &Header, &HeaderSize);
  if (EFI_ERROR (Status)) { goto Done; }
  Status = ParseKernelHeader (Header, HeaderSize, *FileSize, Kernel);
  if (!EFI_ERROR (Status) && (U32 (Header + 12) == 12)) {
    Status = ValidateKernelFileset (File, *FileSize, Header, HeaderSize, Kernel);
  }
  if (!EFI_ERROR (Status)) {
    *FileOut = File;
    Print (L"DARWINBOOT: streaming kernel bytes=%lu header=%lu chunk=%u\n",
           (UINT64)*FileSize, (UINT64)HeaderSize, (UINT32)KERNEL_READ_CHUNK);
  }
Done:
  if (Info != NULL) { FreePool (Info); }
  if (Header != NULL) { FreePool (Header); }
  if (*FileOut == NULL) { File->Close (File); }
  return Status;
}

STATIC
EFI_STATUS
StreamKernel (EFI_FILE_PROTOCOL *File, UINTN FileSize, CONST KERNEL *Kernel,
              EFI_PHYSICAL_ADDRESS Address, UINT64 Capacity)
{
  EFI_STATUS Status;
  UINTN Index;
  CONST SEGMENT *Segment;
  if ((File == NULL) || (Kernel->Count == 0) || (Kernel->Count > MAX_SEGMENTS) ||
      (Kernel->End < Kernel->Base) || (Kernel->End - Kernel->Base > Capacity) ||
      (Address > MAX_UINTN) || (Capacity > MAX_UINTN - Address)) { return EFI_BAD_BUFFER_SIZE; }
  // Validate all ranges before the first destination write.
  for (Index = 0; Index < Kernel->Count; Index++) {
    Segment = &Kernel->Segments[Index];
    if ((Segment->Address < Kernel->Base) || (Segment->Address - Kernel->Base > Capacity) ||
        (Segment->Size > Capacity - (Segment->Address - Kernel->Base)) ||
        (Segment->FileSize > Segment->Size) || (Segment->FileOffset > FileSize) ||
        (Segment->FileSize > FileSize - Segment->FileOffset)) { return EFI_BAD_BUFFER_SIZE; }
  }
  for (Index = 0; Index < Kernel->Count; Index++) {
    Segment = &Kernel->Segments[Index];
    Status = ReadKernelAt (File, FileSize, Segment->FileOffset, (UINTN)Segment->FileSize,
                          (VOID *)(UINTN)(Address + (Segment->Address - Kernel->Base)));
    if (EFI_ERROR (Status)) { return Status; }
  }
  return EFI_SUCCESS;
}
