#include "MyronMemory.h"
// SPDX-License-Identifier: BSD-2-Clause-Patent
#ifndef MYRON27_HANDOFF_H
#define MYRON27_HANDOFF_H
#include <Library/CacheMaintenanceLib.h>
extern CONST UINT8 MyronHandoffStart[], MyronHandoffEnd[];
UINT64 EFIAPI MyronTranslatePage (UINT64 Address);
typedef VOID (EFIAPI *MYRON_ENTRY)(UINT64, UINT64, UINT64, UINT64, UINT64, UINT64);

// Restrict initial hardware qualification to the boot CPU; other CPUs must
// pass the same EL1/EL0 checks before lifting this limit.
STATIC BOOLEAN MyronSingleCpu (CONST CHAR8 *Line)
{
  UINTN Start, End, Count = 0;
  for (Start = 0; Line[Start] != 0; Start = End) {
    while (Line[Start] == ' ' || Line[Start] == '\t') Start++;
    End = Start;
    while (Line[End] != 0 && Line[End] != ' ' && Line[End] != '\t') End++;
    if ((End - Start >= 5) && CompareMem (Line + Start, "cpus=", 5) == 0) {
      if (End - Start != 6 || Line[Start + 5] != '1' || ++Count != 1) return FALSE;
    }
  }
  return Count == 1;
}

STATIC BOOLEAN MyronPacField (UINT64 Value) { return Value != 0 && Value != 15; }
STATIC BOOLEAN MyronPacFeatures (UINT64 Isar1, UINT64 Isar2)
{
  BOOLEAN Address = MyronPacField ((Isar1 >> 4) & 15) || MyronPacField ((Isar1 >> 8) & 15) ||
                    MyronPacField ((Isar2 >> 12) & 15);
  BOOLEAN Generic = MyronPacField ((Isar1 >> 24) & 15) || MyronPacField ((Isar1 >> 28) & 15) ||
                    MyronPacField ((Isar2 >> 8) & 15);
  return Address && Generic;
}

STATIC BOOLEAN MyronIdentityRange (UINT64 Base, UINT64 Size)
{
  UINT64 Page, Last, Par;
  if (Size == 0 || Base > MAX_UINT64 - Size) return FALSE;
  Last = (Base + Size - 1) & ~0xfffULL;
  for (Page = Base & ~0xfffULL; ; Page += EFI_PAGE_SIZE) {
    Par = MyronTranslatePage (Page);
    if ((Par & 1) || (Par & 0x000ffffffffff000ULL) != Page) return FALSE;
    if (Page == Last) break;
  }
  return TRUE;
}

STATIC EFI_STATUS MyronPrepareHandoff (UINT64 Address, UINT64 WindowSize, UINT64 Used,
                                      CONST UINT64 Video[6], UINT64 *Capsule)
{
  UINTN Length = (UINTN)MyronHandoffEnd - (UINTN)MyronHandoffStart;
  UINT64 VideoBytes;
  EFI_STATUS Status;
  *Capsule = 0;
  if ((Address < MYRON_MEMORY_WINDOW_BASE) || (Address & EFI_PAGE_MASK) ||
      (Address > MYRON_MEMORY_WINDOW_END - MYRON_OWNED_MEMORY_SIZE)) return EFI_UNSUPPORTED;
  if (Length != 8192 || WindowSize != MYRON_OWNED_MEMORY_SIZE || Used > WindowSize - SIZE_2MB ||
      Video[2] == 0 || Video[4] > MAX_UINT64 / Video[2]) return EFI_COMPROMISED_DATA;
  VideoBytes = Video[2] * Video[4];
  if (Video[0] == 0 || Video[5] != 32 || Video[3] > Video[2] / 4 || Video[3] < 384 || Video[4] < 512 || VideoBytes < 128 || (VideoBytes & 127)) return EFI_UNSUPPORTED;
  if (!MyronIdentityRange (Address, WindowSize) || !MyronIdentityRange (Video[0], VideoBytes)) {
    DEBUG ((DEBUG_ERROR, "MYRON27: REFUSED nonidentity/unmapped window or GOP\n")); return EFI_UNSUPPORTED;
  }
  UINT64 Target = Address + WindowSize - SIZE_64KB;
  CopyMem ((VOID *)(UINTN)Target, MyronHandoffStart, Length);
  WriteBackDataCacheRange ((VOID *)(UINTN)Target, Length);
  InvalidateInstructionCacheRange ((VOID *)(UINTN)Target, Length);
  Status = gBS->SetWatchdogTimer (0, 0, 0, NULL);
  if (EFI_ERROR (Status)) return Status;
  *Capsule = Target;
  DEBUG ((DEBUG_ERROR, "MYRON27: capsule=%lx bytes=%u identity-pages=verified watchdog=disabled\n", *Capsule, (UINT32)Length));
  return EFI_SUCCESS;
}

// After the first ExitBootServices attempt, call only GetMemoryMap and
// ExitBootServices. Never allocate, print, free, or return into the menu.
#ifndef MYRON_ENTER
#define MYRON_ENTER(Capsule, Args, Entry, Base, Size, Fb, FbSize) \
  ((MYRON_ENTRY)(UINTN)(Capsule))((Args), (Entry), (Base), (Size), (Fb), (FbSize))
#endif
STATIC VOID MyronExitAndEnter (EFI_MEMORY_DESCRIPTOR *Map, UINTN Capacity, UINTN Key,
                              UINT64 Capsule, UINT64 ArgsAddress, UINT64 Entry,
                              UINT64 Address, UINT64 WindowSize, CONST UINT64 Video[6])
{
  EFI_STATUS Status;
  UINTN Attempt, Size, Stride;
  UINT32 Version;
  for (Attempt = 0; Attempt < 3; Attempt++) {
    Status = gBS->ExitBootServices (mImage, Key);
    if (!EFI_ERROR (Status)) {
      MYRON_ENTER (Capsule, ArgsAddress, Entry, Address, WindowSize, Video[0], Video[2] * Video[4]);
      CpuDeadLoop ();
    }
    if (Status != EFI_INVALID_PARAMETER || Attempt == 2) break;
    Size = Capacity;
    Status = gBS->GetMemoryMap (&Size, Map, &Key, &Stride, &Version);
    if (EFI_ERROR (Status)) break;
  }
  // Orange top band: EBS did not complete. Boot services may be partial.
  // This is direct CPU memory access and cache maintenance, no firmware API.
  {
    volatile UINT32 *Fb = (volatile UINT32 *)(UINTN)Video[0];
    UINTN Bytes = (UINTN)(Video[2] * Video[4] / 16), Index;
    for (Index = 0; Index < Bytes / 4; Index++) Fb[Index] = 0xffff8000;
    WriteBackDataCacheRange ((VOID *)(UINTN)Video[0], Bytes);
  }
  CpuDeadLoop ();
}
#endif

