#!/usr/bin/env python3
"""Bounded ADT reader and hardware-contract comparison for myron bring-up."""
import struct


def parse(blob):
    if not 8 <= len(blob) <= 256 * 1024:
        raise ValueError('ADT size outside bounds')
    nodes = {}
    def walk(at, parent, depth):
        if depth > 24 or at + 8 > len(blob): raise ValueError('ADT depth/header')
        count, children = struct.unpack_from('<II', blob, at); at += 8
        if count > 256 or children > 256: raise ValueError('ADT count')
        props = {}
        for _ in range(count):
            if at + 36 > len(blob): raise ValueError('ADT property header')
            key, size = struct.unpack_from('<32sI', blob, at); at += 36
            if b'\0' not in key or size > len(blob) - at: raise ValueError('ADT property extent')
            key = key.split(b'\0')[0].decode('ascii')
            if key in props: raise ValueError('Duplicate ADT property')
            props[key] = blob[at:at + size]; at = (at + size + 3) & ~3
            if at > len(blob): raise ValueError('ADT padding')
        name = props.get('name', b'')
        if not name.endswith(b'\0') or b'\0' in name[:-1] or b'/' in name:
            raise ValueError('ADT node name')
        path = parent + '/' + name[:-1].decode('ascii')
        if path in nodes: raise ValueError('Duplicate ADT node')
        nodes[path] = props
        for _ in range(children): at = walk(at, path, depth + 1)
        return at
    if walk(0, '', 0) != len(blob): raise ValueError('ADT trailing bytes')
    return nodes


def validate(blob, reference):
    new, old = parse(blob), parse(reference)
    root = '/device-tree'; chosen = new[root + '/chosen']
    assert new[root]['model'] == b'iPhone12,1\0'
    assert new[root]['target-type'] == b'N104\0'
    assert new[root]['compatible'].split(b'\0')[:3] == [b'N104AP', b'xiaomi,myron', b'qcom,sm8850']
    assert chosen['chip-id'] == struct.pack('<I', 0x8030)
    assert chosen['unique-chip-id'] == old[root + '/chosen']['unique-chip-id']
    assert len(chosen['unique-chip-id']) == 8 and any(chosen['unique-chip-id'])
    assert len(chosen['random-seed']) == 256 and any(chosen['random-seed'])
    assert chosen.get('kernel-ctrr-to-be-enabled') == struct.pack('<I', 0)
    for key, value in [('dram-base', 0x8c0000000), ('dram-size', 0x82000000), ('darwinboot-memory-size', 0x80000000)]:
        assert chosen[key] == old[root + '/chosen'][key] == struct.pack('<Q', value)
    # Neither the old iPad instruction patches nor its root-volume selection
    # and sidecar pointers may leak into this initial iPhone kernel handoff.
    assert 'text-fixups' not in chosen and 'root-matching' not in chosen
    assert set(new[root + '/chosen/memory-map']) == {'name'}
    hardware = [path for path in old if path.startswith(root + '/cpus') or
                path.startswith(root + '/arm-io') or path == root + '/psci']
    for path in hardware: assert new[path] == old[path], path
    assert new[root + '/defaults'] == old[root + '/defaults']
    return dict(result='passed', hardware_nodes_matched=len(hardware), cpu_nodes=8,
                boot_cpu_limit=1, random_seed_bytes=256, identity='iPhone12,1/N104AP/0x8030',
                platform_seed_preserved=True, owned_memory_bytes=0x80000000,
                apple_ctrr_declared_enabled=False,
                old_ipad_text_fixups_absent=True, root_selection_absent=True,
                sidecar_pointers_absent=True, phone_tested=False)

