#!/usr/bin/env python3
"""Exercise the real firmware FAT policy and new ADT with negative inputs."""
import argparse
import json
import os
from pathlib import Path
import struct
import subprocess
import sys
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from payload_adt import parse, validate
p = argparse.ArgumentParser()
for n in ('payload', 'reference-adt', 'out'): p.add_argument('--' + n, type=Path, required=True)
p.add_argument('--board', type=Path)
p.add_argument('--adt-only', action='store_true', help='run ADT contract cases without claiming FAT policy coverage')
a = p.parse_args(); a.out.mkdir(parents=True, exist_ok=True)
if not a.adt_only and a.board is None: p.error('--board is required unless --adt-only')
if not a.adt_only:
    policy = a.board.resolve() / 'Library/PlatformPeiLib'
    source = a.out / 'policy.c'
    source.write_text('''#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#define STATIC static
#define CONST const
#define BOOLEAN int
#define TRUE 1
#define FALSE 0
#define UINT8 uint8_t
#define UINT32 uint32_t
#define UINT64 uint64_t
#define MAX_UINT32 UINT32_MAX
#define CompareMem memcmp
#include "PayloadPolicy.h"
#include "KernelPayloadExpected.h"
int main(int argc,char **argv){
 assert(argc==2); unsigned char b[512],c[512]; FILE*f=fopen(argv[1],"rb");assert(f);
 assert(fread(b,1,512,f)==512);fclose(f);
 assert(MYRON_KERNEL_FAT_BYTES==88ULL*1024*1024);
 assert(MyronFatPayload(b,MYRON_KERNEL_FAT_BYTES));
 assert(!MyronFatPayload(b,64ULL*1024*1024));
 assert(!MyronFatPayload(b,MYRON_KERNEL_FAT_BYTES-1));
 unsigned offsets[]={0,2,11,14,16,17,19,22,28,32,42,66,71,82,510};
 for(unsigned i=0;i<sizeof(offsets)/sizeof(offsets[0]);i++){
  memcpy(c,b,512);if(offsets[i]==14)c[14]=c[15]=0;else c[offsets[i]]^=0x80;assert(!MyronFatPayload(c,MYRON_KERNEL_FAT_BYTES));
 }
 puts("FAT policy passed: valid 88 MiB, wrong sizes, 15 corrupt BPBs");return 0;
}''')
    exe = a.out / 'policy-test'
    subprocess.run(['gcc', '-Wall', '-Wextra', '-Werror', '-fsanitize=address,undefined',
                    '-I' + str(policy), str(source), '-o', str(exe)], check=True)
    r = subprocess.run([str(exe.resolve()), str(a.payload.resolve() / 'payload.img')], capture_output=True,
                       text=True, check=True, env=dict(os.environ, ASAN_OPTIONS='detect_leaks=0:halt_on_error=1', UBSAN_OPTIONS='halt_on_error=1'))
    (a.out / 'policy.log').write_text(r.stdout + r.stderr)
adt = (a.payload / 'stage/EFI/UniXNU/Payloads/kernel.macho.adt').read_bytes()
ref = a.reference_adt.read_bytes(); validate(adt, ref)
bad = [b'', adt[:7], adt[:-1], adt + b'\0', struct.pack('<II', 1000, 0) + adt[8:]]
for blob in bad:
    try: parse(blob)
    except (ValueError, UnicodeError): pass
    else: raise AssertionError('Malformed ADT accepted')
for key in ('chip-id', 'dram-base', 'unique-chip-id', 'random-seed', 'timebase-frequency', 'kernel-ctrr-to-be-enabled'):
    blob = bytearray(adt); marker = key.encode().ljust(32, b'\0'); at = blob.index(marker)
    if key == 'random-seed': struct.pack_into('<I', blob, at + 32, 64)
    else: blob[at + 36] ^= 1
    try: validate(bytes(blob), ref)
    except (AssertionError, ValueError, UnicodeError): pass
    else: raise AssertionError('Changed ADT contract accepted: ' + key)
missing = adt.replace(b'kernel-ctrr-to-be-enabled'.ljust(32, b'\0'), b'unused-ctrr-declaration'.ljust(32, b'\0'))
assert missing != adt
try: validate(missing, ref)
except AssertionError: pass
else: raise AssertionError('Missing CTRR boot declaration accepted')
report = dict(result='passed', fat_policy_cases=0 if a.adt_only else 18, adt_cases=13,
              production_fat_policy_executed=not a.adt_only, sanitizer=None if a.adt_only else 'address,undefined',
              leak_sanitizer=False, phone_tested=False)
(a.out / 'payload-tests.json').write_text(json.dumps(report, indent=2) + '\n'); print(json.dumps(report))

