#!/usr/bin/env python3
"""Private actual-kernel replay. QEMU virt is not an SM8850 hardware model.

Inputs are a verified fileset, test_loader_boot.py --capture output and the
unmodified capsule ELF from test_handoff_qemu.py. No instruction/PAC hooks.
Optional ADT/command overrides are reported and never modify original inputs.
"""
import argparse, bisect, hashlib, json, os, re, select, struct, subprocess, sys, time
import xml.etree.ElementTree as ET
from pathlib import Path


class RegisterReader:
    """Read-only GDB register packets, used only while QMP has stopped the VM."""
    def __init__(self, path):
        self.output = os.open(str(path)+'.in', os.O_RDWR)
        self.input = os.open(str(path)+'.out', os.O_RDWR)
        self.packet('qSupported:xmlRegisters=aarch64')
        self.registers = {}
        number = 0
        def xml(name):
            nonlocal number
            data = bytearray()
            while True:
                chunk = self.packet(f'qXfer:features:read:{name}:{len(data):x},1000')
                assert chunk[:1] in (b'm', b'l'), chunk
                data += chunk[1:]
                if chunk[:1] == b'l': break
            # QEMU's target.xml uses xi:include without a namespace declaration.
            for node in ET.fromstring(data.replace(b'xi:include', b'include')).iter():
                if node.tag.endswith('include'):
                    xml(node.attrib['href'])
                elif node.tag == 'reg':
                    number = int(node.attrib.get('regnum', number))
                    self.registers[node.attrib['name']] = number
                    number += 1
        xml('target.xml')

    def packet(self, command):
        data = command.encode('ascii')
        os.write(self.output, b'$'+data+b'#'+f'{sum(data)&255:02x}'.encode())
        while self.receive(1) != b'$': pass
        encoded = bytearray()
        while True:
            b = self.receive(1)
            if not b: raise RuntimeError('GDB connection closed')
            if b == b'#': break
            encoded += b
        checksum = bytearray()
        while len(checksum)<2: checksum += self.receive(2-len(checksum))
        assert sum(encoded)&255 == int(checksum,16), 'GDB checksum mismatch'
        os.write(self.output, b'+')
        result = bytearray(); i = 0
        while i < len(encoded):
            b = encoded[i]; i += 1
            if b == 125:
                result.append(encoded[i]^32); i += 1
            elif b == 42:
                result.extend([result[-1]]*(encoded[i]-29)); i += 1
            else: result.append(b)
        return bytes(result)

    def read(self):
        values = {}
        for name, number in self.registers.items():
            if name.upper().startswith(('CNT', 'ICC_', 'TPIDR_EL1', 'DAIF')):
                value = self.packet(f'p{number:x}')
                if not value.startswith(b'E') and value:
                    values[name] = hex(int.from_bytes(bytes.fromhex(value.decode()), 'little'))
        return values

    def close(self):
        os.close(self.input)
        os.close(self.output)

    def receive(self, count):
        if not select.select([self.input], [], [], 5)[0]:
            raise TimeoutError('GDB pipe read timed out')
        return os.read(self.input, count)


def main():
    p = argparse.ArgumentParser(description=__doc__)
    for name in ('kernel', 'capture', 'capsule-elf', 'xnuprelink', 'qemu', 'clang', 'out'):
        p.add_argument('--'+name, type=Path, required=True)
    p.add_argument('--seconds', type=int, default=20)
    p.add_argument('--command', help='explicit replay-only ASCII boot argument override')
    p.add_argument('--virtual-gic', action='store_true')
    p.add_argument('--virtual-timebase', action='store_true')
    p.add_argument('--counter-frequency', type=int, choices=(19200000,62500000), default=19200000,
                   help='QEMU architectural counter frequency; default matches myron ADT')
    p.add_argument('--keep-ram', action='store_true')
    p.add_argument('--inspect-timers', action='store_true', help='read architectural registers through local GDB pipes')
    a = p.parse_args()
    assert 4 <= a.seconds <= 600 and (not a.virtual_timebase or a.virtual_gic)
    assert not a.virtual_timebase or a.counter_frequency == 62500000
    assert not a.out.exists(), 'use fresh output'
    a.out.mkdir(parents=True)
    sys.path.insert(0, str(a.xnuprelink.resolve()))
    sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
    from kc_image import Image
    from elftools.elf.elffile import ELFFile
    from payload_adt import parse
    im = Image(a.kernel.read_bytes())
    kernel = Image(im.data, im.entries['com.apple.kernel'][1])
    symbols = kernel.symbols(); keys = sorted(symbols)
    byname = {n: v for v, names in symbols.items() for n in names}
    h = json.loads((a.capture/'handoff.json').read_text())
    original = (a.capture/'loaded.bin').read_bytes(); data = bytearray(original)
    assert len(data) == h['bytes'] < 0x80000000-0x10000
    for s in im.segments:
        at = s['va']-im.base
        assert data[at:at+s['filesize']] == im.data[s['fileoff']:s['fileoff']+s['filesize']]
    arg = h['args']-h['base']; assert struct.unpack_from('<Q',data,arg+8)[0] == im.base
    overrides = ['host GOP pointer -> 0xfc800000 observed board framebuffer']
    struct.pack_into('<Q', data, arg+40, 0xfc800000)
    if a.command is not None:
        cmd = a.command.encode('ascii'); assert len(cmd)<1024 and b'\0' not in cmd
        data[arg+108:arg+1132] = cmd+bytes(1024-len(cmd)); overrides.append('boot arguments overridden')
    command = data[arg+108:arg+1132].split(b'\0')[0].decode('ascii')
    if a.virtual_gic:
        tree, size = struct.unpack_from('<QI', data, arg+96); offset = tree-im.base
        blob = bytes(data[offset:offset+size]); nodes = parse(blob)
        replacements = {('/device-tree/arm-io','ranges'):struct.pack('<3Q',0,0x08000000,0x1000000),
            ('/device-tree/arm-io/intc','reg'):struct.pack('<4Q',0,0x10000,0xa0000,0x200000),
            ('/device-tree/arm-io/intc','redistributor-stride'):struct.pack('<Q',0x20000)}
        for (path, key), value in replacements.items():
            old = nodes[path][key]; assert len(old)==len(value)
            marker = key.encode().ljust(32,b'\0')+struct.pack('<I',len(old))
            assert blob.count(marker+old)==1
            blob=blob.replace(marker+old,marker+value);overrides.append(path+':'+key+' -> QEMU virt')
        if a.virtual_timebase:
            props=[v['timebase-frequency'] for n,v in nodes.items() if n.startswith('/device-tree/cpus/') and 'timebase-frequency' in v]
            assert props and all(x==struct.pack('<I',19200000) for x in props)
            marker=b'timebase-frequency'.ljust(32,b'\0')+struct.pack('<I',4)
            assert blob.count(marker+props[0])==len(props)
            blob=blob.replace(marker+props[0],marker+struct.pack('<I',62500000))
            overrides.append('CPU timebase-frequency -> 62500000 Hz')
        data[offset:offset+size]=blob
    (a.out/'replay.bin').write_bytes(data)
    with a.capsule_elf.open('rb') as f:
        elf=ELFFile(f); syms={s.name:s['st_value'] for s in elf.get_section_by_name('.symtab').iter_symbols()}
        lo,hi=syms['MyronHandoffStart'],syms['MyronHandoffEnd']
        capsule=next(s.data()[lo-s['p_vaddr']:hi-s['p_vaddr']] for s in elf.iter_segments() if s['p_vaddr']<=lo<hi<=s['p_vaddr']+s['p_filesz'])
    assert len(capsule)==8192
    (a.out/'capsule.bin').write_bytes(capsule);cap=h['base']+0x80000000-0x10000
    (a.out/'start.S').write_text(f'.text\n.global _start\n_start:\n ldr x0, ={h["args"]}\n ldr x1, ={h["entry"]}\n ldr x2, ={h["base"]}\n mov x3, #0x80000000\n ldr x4, =0xfc800000\n ldr x5, =0xbf0400\n ldr x9, ={cap}\n br x9\n')
    (a.out/'link.ld').write_text('ENTRY(_start)\nSECTIONS { . = 0x40080000; .text : { *(.text) } }\n')
    subprocess.run([str(a.clang),'--target=aarch64-none-elf','-nostdlib','-fuse-ld=lld','-Wl,-T,'+str(a.out/'link.ld'),str(a.out/'start.S'),'-o',str(a.out/'start.elf')],check=True)
    ram=a.out/'ram.bin'
    q=[str(a.qemu),'-M','virt,gic-version=3,memory-backend=ram0','-cpu',f'max,cntfrq={a.counter_frequency}','-m','38G','-object',f'memory-backend-file,id=ram0,size=38G,mem-path={ram},share=on,prealloc=off','-icount','shift=0,align=off,sleep=off','-nodefaults','-nographic','-monitor','none','-serial','none','-kernel',str(a.out/'start.elf'),'-qmp','stdio','-S','-d','guest_errors,unimp','-D',str(a.out/'guest.log')]
    if a.inspect_timers:
        for suffix in ('.in', '.out'): os.mkfifo(str(a.out/'gdb')+suffix, 0o600)
        q += ['-chardev',f'pipe,path={a.out}/gdb,id=regs','-gdb','chardev:regs']
    for name,addr in [('replay.bin',h['base']),('capsule.bin',cap)]:q+=['-device',f'loader,file={a.out/name},addr={addr},force-raw=on']
    (a.out/'command.json').write_text(json.dumps(q,indent=2)+'\n')
    def describe(lr):
        v=(lr&0xfffffffff)|0xfffffff000000000
        owner=next((name for name,(_,at) in im.entries.items() if any(s['va']<=v<s['va']+s['size'] for s in Image(im.data,at).segments)),None)
        i=bisect.bisect_right(keys,v)-1
        return dict(address=hex(v),owner=owner,symbol=symbols[keys[i]] if i>=0 and owner=='com.apple.kernel' else None,offset=hex(v-keys[i]) if i>=0 and owner=='com.apple.kernel' else None)
    snapshots=[]
    def inspect(regs):
        with ram.open('rb') as f:
            def pa(v,n):
                assert 0x40000000<=v<0x40000000+38*1024**3
                f.seek(v-0x40000000);return f.read(n)
            def linear(v,n):return pa(v-im.base+h['base'],n)
            def value(name,n=8):return int.from_bytes(linear(byname[name],n),'little')
            table=value('_cpu_ttep')
            def translate(v):
                t=table
                for sh in (30,21,12):
                    d=int.from_bytes(pa(t+((v>>sh)&(255 if sh==30 else 511))*8,8),'little')
                    if not d&1:raise ValueError('unmapped')
                    if sh==12 or d&3==1:return ((d&0xfffffffff000)&~((1<<sh)-1))|(v&((1<<sh)-1))
                    t=d&0xfffffffff000
            def read(v,n):
                b=bytearray()
                while n:
                    k=min(n,4096-(v&4095));b+=pa(translate(v),k);v+=k;n-=k
                return bytes(b)
            ptr=value('_debugger_panic_str');panic=read(ptr,512).split(b'\0')[0].decode(errors='replace') if ptr else None
            fp=int(re.search('X29=([0-9a-f]+)',regs)[1],16);frames=[]
            for _ in range(32):
                try:prev,lr=struct.unpack('<QQ',read(fp,16))
                except (AssertionError,ValueError):break
                frames.append(dict(fp=hex(fp),**describe(lr)))
                if not fp<prev<fp+0x10000:break
                fp=prev
            counters={}
            for n in ['_armcpu_registered','_armcpu_gic_ready','_armcpu_timer_interrupts','_armcpu_gic_diag_stage','_armdt_platform_cpu_count',
                      '_myron_storage_boot_claimed','_myron_storage_boot_stage','_myron_storage_boot_status',
                      '_myron_storage_registration_state','_myron_storage_registration_status','_myron_ufs_probe_calls']:
                if n in byname:counters[n]=value(n,8 if n.endswith('_interrupts') else 4)
            console = {}
            if '_msgbufp' in byname and value('_msgbufp'):
                try:
                    # bsd/sys/msgbuf.h, XNU 12377: four int32 fields, then a pointer.
                    magic,size,x,r,ptr=struct.unpack('<4IQ',read(value('_msgbufp'),24))
                    assert magic==0x063061 and 0<size<=1024*1024 and x<size and r<size
                    buf=read(ptr,size)
                    output=(buf[x:]+buf[:x]).replace(b'\0',b'')
                    (a.out/'kernel-console.txt').write_bytes(output)
                    console=dict(console_sha256=hashlib.sha256(output).hexdigest(),
                                 console_bytes=len(output),
                                 root_media_wait_observed=b'Waiting on <dict' in output and b'IOMedia' in output)
                except (ValueError, AssertionError, struct.error):
                    console=dict(console_unavailable=True)
            return dict(panic=panic,frames=frames,counters=counters,pc=describe(int(re.search('PC=([0-9a-f]+)',regs)[1],16)),**console)
    with (a.out/'qemu.log').open('w') as log:
        proc=subprocess.Popen(q,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=log)
        def call(cmd,args=None):
            proc.stdin.write((json.dumps({'execute':cmd,'arguments':args or {}})+'\n').encode());proc.stdin.flush()
            while True:
                line=proc.stdout.readline()
                if not line:raise RuntimeError('QEMU exited')
                r=json.loads(line)
                if 'return' in r:return r['return']
                if 'error' in r:raise RuntimeError(r)
        reader = None
        try:
            json.loads(proc.stdout.readline());call('qmp_capabilities')
            if a.inspect_timers: reader = RegisterReader(a.out/'gdb')
            call('cont')
            for i in range((a.seconds+1)//2):
                time.sleep(2);call('stop')
                regs=call('human-monitor-command',{'command-line':'info registers'})
                (a.out/f'registers-{i}.txt').write_text(regs)
                state=inspect(regs);state['wall_seconds']=(i+1)*2
                if reader: state['architectural_registers'] = reader.read()
                snapshots.append(state)
                (a.out/'snapshots.json').write_text(json.dumps(snapshots,indent=2)+'\n')
                if state['panic']: break
                call('cont')
            call('stop');call('quit');proc.wait(timeout=3)
        finally:
            if reader: reader.close()
            if proc.poll() is None:proc.kill();proc.wait()
    report=dict(result='observed',kernel_sha256=hashlib.sha256(im.data).hexdigest(),capture_sha256=hashlib.sha256(original).hexdigest(),capsule_sha256=hashlib.sha256(capsule).hexdigest(),kernel_args=command,replay_overrides=overrides,virtual_gic=a.virtual_gic,virtual_timebase=a.virtual_timebase,counter_frequency_hz=a.counter_frequency,instruction_patches=False,pac_hooks=False,uefi_capture_mocked=True,snapshots=snapshots,phone_tested=False,desktop_reached=False,limitations=['QEMU virt is not SM8850; timing and peripherals differ.','No root volume. Absence of panic is not boot success.'])
