// SPDX-License-Identifier: BSD-2-Clause-Patent
// Included with the pinned upstream bridge staged by check_ufs_transport.py.
// Inject ownership changes at lock acquisition, after argument validation.
#include "RootCommandsBridge.cpp"
#include <array>
#include <cstdlib>

static unsigned fault, locks, unlocks, writes, dma;
static uint64_t io(unsigned op, uint64_t address, uint64_t, void *)
{
  if (op == 6) {
    ++locks;
    if (fault == 1) { gHost.ready = false; gHost.poisoned = true; }
  }
  if (op == 7) ++unlocks;
  if (op == 1) ++writes;
  if (op == 2 || op == 3) ++dma;
  if (op == 0 && address == 0x58 && fault == 2) return 1;
  if (op == 0 && address == 0x20 && fault == 3) return kUfsFatalStatus;
  return 0;
}

int main(int argc, char **argv)
{
  const bool fixed = argc == 2 && !strcmp(argv[1], "--expect-fixed");
  unsigned changed = 0;
  for (fault = 1; fault <= 3; ++fault) {
    locks = unlocks = writes = dma = 0;
    ufs_test_reset(io, 0x8cb5e9000);
    assert(ufs_test_store_open(448, 32));
    std::array<uint8_t, 4096> source;
    source.fill(0x5a);
    std::array<uint8_t, kDmaBytes> before;
    memcpy(before.data(), memory, sizeof(memory));
    auto status = ufs_test_write(0, 448, 1, source.data());
    assert(status == kIOReturnNotReady && gHost.poisoned && !gHost.ready);
    assert(locks == 1 && unlocks == 1 && !writes && !dma);
    bool preserved = !memcmp(before.data(), memory, sizeof(memory));
    if (!preserved) ++changed;
    printf("case=%u status=%#x DMA_preserved=%u\n", fault, status, preserved);
    assert(preserved == fixed);
    // All later operations must leave the quarantined buffer untouched too.
    if (fixed) {
      assert(ufs_test_write(0, 449, 1, source.data()) == kIOReturnNotReady);
      assert(!memcmp(before.data(), memory, sizeof(memory)) && !writes && !dma);
      assert(locks == 2 && unlocks == 2);
    }
  }
  assert(changed == (fixed ? 0U : 3U));
  puts(fixed ? "PASS: all three ownership failures preserve DMA" :
               "REPRODUCED: upstream changes DMA in all three ownership failures");
  return 0;
}

