// SPDX-License-Identifier: BSD-2-Clause-Patent
// Exercise the production loader using the generated, compiled trust inputs.
#include "MyronRootPolicyData.h"
#include "verified_root.h"
#include <openssl/sha.h>
#include <cassert>
#include <cstring>
#include <fstream>
#include <iterator>
#include <vector>
#include <iostream>
extern "C" int vr_host_open(const void *, size_t, const void *, uint64_t, vr_view *);

static std::vector<uint8_t> bytes(const char *path) {
  std::ifstream f(path, std::ios::binary);
  assert(f.good());
  return {std::istreambuf_iterator<char>(f), {}};
}
int main(int argc, char **argv) {
  assert(argc == 3);
  const auto root = bytes(argv[1]), carrier = bytes(argv[2]);
  uint8_t scratch[4096];
  unsigned reads = 0, largest = 0, fail = 0, corrupt = 0;
  auto read = [&](uint64_t lba, unsigned count, void *destination) {
    ++reads; largest = count > largest ? count : largest;
    assert(count && count <= 32);
    assert(lba >= myron_root_geometry.first && lba + count - 1 <= myron_root_geometry.last);
    if (reads == fail) return false;
    const uint64_t offset = (lba - myron_root_geometry.first) * 4096;
    const auto &source = offset < myron_root_geometry.carrierOffset ? root : carrier;
    const uint64_t at = offset < myron_root_geometry.carrierOffset ? offset : offset - myron_root_geometry.carrierOffset;
    assert(at <= source.size() && uint64_t(count) * 4096 <= source.size() - at);
    memcpy(destination, source.data() + at, count * 4096);
    if (reads == corrupt) static_cast<uint8_t *>(destination)[0] ^= 1;
    return true;
  };
  auto hash = [](const void *data, uint64_t size, uint8_t digest[32]) {
    return SHA256(static_cast<const uint8_t *>(data), size, digest) != nullptr;
  };
  auto load = [&](const MyronRootGeometry &g, uint64_t diskLast,
                  const MyronPolicyRegion *regions = myron_policy_regions) {
    reads = largest = 0;
    return myronLoadPolicies(g, myron_root_geometry.first, myron_root_geometry.last,
        diskLast, regions, 2, scratch, myron_root_header_sha256,
        myron_carrier_header_sha256, read, hash);
  };
  const auto g = myron_root_geometry;
  assert(myron_root_guid[0] != 0 && verified_root_policy_count == 2);
  assert(load(g, g.diskLast) == PolicyOK && largest == 32);
  const unsigned successfulReads = reads;
  for (unsigned i = 0; i < 2; ++i) {
    const auto &p = verified_root_policies[i];
    assert(!memcmp(p.manifest, carrier.data() + myron_policy_regions[i].offset, p.manifestBytes));
    vr_view view{};
    assert(vr_host_open(p.manifest, p.manifestBytes, verified_root_key, 1, &view) == 0);
    assert(view.generation == 7);
  }
  // Every failed I/O stops the sequence immediately; no later read occurs.
  for (unsigned i = 1; i <= successfulReads; ++i) {
    fail = i;
    assert(load(g, g.diskLast) == (i == 1 ? PolicyRootRead : i == 2 ? PolicyHeaderRead : PolicyRead));
    assert(reads == i);
  }
  fail = 0;
  for (unsigned i = 1; i <= successfulReads; ++i) {
    corrupt = i;
    assert(load(g, g.diskLast) == (i == 1 ? PolicyRootHash : i == 2 ? PolicyHeaderHash : PolicyHash));
  }
  corrupt = 0;
  assert(load(g, g.diskLast + 1) == PolicyGeometry && reads == 0);
  auto wrong = g; wrong.first++;
  assert(load(wrong, g.diskLast) == PolicyGeometry && reads == 0);
  wrong = g; wrong.last--;
  assert(load(wrong, g.diskLast) == PolicyGeometry && reads == 0);
  wrong = g; wrong.carrierOffset = 0;
  assert(load(wrong, g.diskLast) == PolicyGeometry && reads == 0);
  wrong = g; wrong.carrierCapacity = UINT64_MAX;
  assert(load(wrong, g.diskLast) == PolicyGeometry && reads == 0);
  wrong = g; wrong.reserveBlocks = 1;
  assert(load(wrong, g.diskLast) == PolicyGeometry && reads == 0);
  wrong = g; wrong.diskLast = UINT64_MAX;
  assert(load(wrong, wrong.diskLast) == PolicyGeometry && reads == 0);
  // Check the original 32 GiB geometry remains representable, without using it
  // as a default or accessing a device with it.
  assert(myronRootGeometryValid({249424640,257813247,257813503,
      31ULL*1024*1024*1024,128ULL*1024*1024,256ULL*1024}));
  MyronPolicyRegion regions[2] = {myron_policy_regions[0], myron_policy_regions[1]};
  regions[1].offset += 4096;
  assert(load(g, g.diskLast, regions) == PolicyDescriptor && reads == 0);
  regions[1] = myron_policy_regions[1]; regions[0].bytes = UINT64_MAX;
  assert(load(g, g.diskLast, regions) == PolicyDescriptor && reads == 0);
  regions[0] = myron_policy_regions[0]; regions[0].destination = nullptr;
  assert(load(g, g.diskLast, regions) == PolicyDescriptor && reads == 0);
  std::cout << "PASS generated inputs -> production loader -> real signature verifier; "
            << successfulReads << " reads, 32-block chunk, all I/O fault positions, geometry/descriptors\n";
}

