// SPDX-License-Identifier: BSD-2-Clause-Patent
#pragma once
#include <stdint.h>
#include <stddef.h>

struct MyronPolicyRegion {
  uint64_t offset, bytes, capacity;
  uint8_t *destination;
  const uint8_t *sha256;
};

// Installation geometry is compiled from an explicitly reviewed root bundle.
// Never discover a write target or infer a partition from these values.
struct MyronRootGeometry {
  uint64_t first, last, diskLast, carrierOffset, carrierCapacity, reserveBlocks;
};

static inline bool myronRootGeometryValid(const MyronRootGeometry &g)
{
  if (g.first < 6 || g.last < g.first || g.diskLast > UINT32_MAX ||
      g.last >= g.diskLast || g.diskLast - g.last < 5) return false;
  const uint64_t blocks = g.last - g.first + 1;
  const uint64_t bytes = blocks * 4096;
  // reserveBlocks() uses integral MiB, with the same 16 GiB upper limit.
  if (!g.reserveBlocks || (g.reserveBlocks & 255) ||
      g.reserveBlocks > 16384ULL * 256 || g.reserveBlocks >= blocks) return false;
  if ((g.carrierOffset & 4095) || (g.carrierCapacity & 4095) ||
      g.carrierCapacity < 4096 || g.carrierCapacity > 128ULL * 1024 * 1024 ||
      g.carrierOffset < (blocks - g.reserveBlocks) * 4096 ||
      g.carrierOffset >= bytes || g.carrierCapacity > bytes - g.carrierOffset) return false;
  return true;
}

enum MyronPolicyResult {
  PolicyOK, PolicyGeometry, PolicyRootRead, PolicyRootHash,
  PolicyHeaderRead, PolicyHeaderHash, PolicyDescriptor,
  PolicyRead, PolicyHash
};

// All metadata and digests are compiled trust inputs, never parsed from disk.
// Read at most 32 physical 4K blocks per request; stop on the first failed I/O.
template<class Read, class Hash>
MyronPolicyResult myronLoadPolicies(const MyronRootGeometry &geometry,
    uint64_t first, uint64_t last,
    uint64_t diskLast, const MyronPolicyRegion *regions, unsigned count,
    uint8_t *scratch, const uint8_t *rootHash, const uint8_t *headerHash,
    Read read, Hash hash)
{
  const uint64_t offset = geometry.carrierOffset, limit = geometry.carrierCapacity;
  if (!myronRootGeometryValid(geometry) || first != geometry.first ||
      last != geometry.last || diskLast != geometry.diskLast ||
      !scratch || !rootHash || !headerHash || !regions || count != 2)
    return PolicyGeometry;
  uint64_t previous = 4096;
  for (unsigned i = 0; i < count; ++i) {
    const auto &r = regions[i];
    if (!r.destination || !r.sha256 || r.bytes < 544 || r.bytes > r.capacity ||
        r.capacity > limit || r.bytes > UINT64_MAX - 4095 ||
        r.capacity != ((r.bytes + 4095) & ~4095ULL) ||
        (r.offset & 4095) || r.offset != previous || r.offset > limit - r.capacity)
      return PolicyDescriptor;
    previous = r.offset + r.capacity;
  }
  auto matches = [&hash](const void *data, uint64_t bytes, const uint8_t *wanted) {
    uint8_t actual[32];
    if (!hash(data, bytes, actual)) return false;
    uint8_t difference = 0;
    for (unsigned i = 0; i < 32; ++i) difference |= actual[i] ^ wanted[i];
    return difference == 0;
  };
  if (!read(first, 1, scratch)) return PolicyRootRead;
  if (!matches(scratch, 4096, rootHash)) return PolicyRootHash;
  const uint64_t base = first + offset / 4096;
  if (!read(base, 1, scratch)) return PolicyHeaderRead;
  if (!matches(scratch, 4096, headerHash)) return PolicyHeaderHash;
  for (unsigned i = 0; i < count; ++i) {
    const auto &r = regions[i];
    for (uint64_t at = 0; at < r.capacity; ) {
      unsigned blocks = unsigned((r.capacity - at) / 4096);
      if (blocks > 32) blocks = 32;
      if (!read(base + (r.offset + at) / 4096, blocks, r.destination + at))
        return PolicyRead;
      at += uint64_t(blocks) * 4096;
    }
    if (!matches(r.destination, r.bytes, r.sha256)) return PolicyHash;
  }
  return PolicyOK;
}

