// SPDX-License-Identifier: BSD-2-Clause-Patent
// UFS-only integration of UniXNU's signed media/provider identity contract.
// Included after NativeUfs.cpp and probeStatus; no matching personality added.
#include <sys/conf.h>
#include "MyronRootIdentity.h"

extern "C" {
volatile uint32_t myron_root_start_ready = 0;
extern volatile int native_owner_root_accepted, native_owner_root_readonly;
extern volatile dev_t native_owner_root_mount_device, native_owner_root_selected_device;
}

static int myronAuthenticateDevice(dev_t device, const char *expectedUUID, uint8_t *digest)
{
  if (myron_root_start_ready != 1 || device == NODEV) return 0;
  uint8_t candidateDigest[48] = {};
  const uint32_t mj = major(static_cast<uint32_t>(device));
  const uint32_t mn = minor(static_cast<uint32_t>(device));
  OSDictionary *matching = IOService::serviceMatching("IOMedia");
  OSDictionary *properties = OSDictionary::withCapacity(2);
  OSNumber *mjr = OSNumber::withNumber(mj, 32), *mnr = OSNumber::withNumber(mn, 32);
  if (!matching || !properties || !mjr || !mnr) {
    OSSafeReleaseNULL(mnr); OSSafeReleaseNULL(mjr);
    OSSafeReleaseNULL(properties); OSSafeReleaseNULL(matching);
    return 0;
  }
  bool ready = properties->setObject(kIOBSDMajorKey, mjr) &&
      properties->setObject(kIOBSDMinorKey, mnr) && matching->setObject("IOPropertyMatch", properties);
  mjr->release(); mnr->release(); properties->release();
  OSIterator *iterator = ready ? IOService::getMatchingServices(matching) : nullptr;
  matching->release();
  if (!iterator) return 0;
  struct Operations {
    OSIterator *iterator;
    const char *expectedUUID;
    uint8_t *digest;
    bool ready() { return myron_root_start_ready == 1; }
    IOService *next() {
      while (OSObject *object = iterator->getNextObject())
        if (IOService *service = OSDynamicCast(IOService, object)) return service;
      return nullptr;
    }
    bool identity(IOService *media, uint32_t mj, uint32_t mn, const char **out) {
      OSNumber *mjr = OSDynamicCast(OSNumber, media->getProperty(kIOBSDMajorKey));
      OSNumber *mnr = OSDynamicCast(OSNumber, media->getProperty(kIOBSDMinorKey));
      OSString *uuid = OSDynamicCast(OSString, media->getProperty("UUID"));
      if (!mjr || !mnr || mjr->unsigned64BitValue() != mj || mnr->unsigned64BitValue() != mn ||
          !uuid || uuid->getLength() != 36 ||
          (expectedUUID && strcmp(uuid->getCStringNoCopy(), expectedUUID))) return false;
      *out = uuid->getCStringNoCopy();
      return true;
    }
    IOService *parent(IOService *service) { return service->getProvider(); }
    int authenticate(IOService *provider, const char *uuid) {
      return native_ufs_block_authenticates(provider, uuid, digest);
    }
  } operations = {iterator, expectedUUID, digest ? candidateDigest : nullptr};
  bool authenticated = myronAuthenticateRootMedia(operations, mj, mn);
  iterator->release();
  // Publish output only after unique media and the complete provider walk pass.
  if (authenticated && digest) memcpy(digest, candidateDigest, sizeof(candidateDigest));
  return authenticated ? 1 : 0;
}

extern "C" int native_verified_block_root_authorized(dev_t device)
{
  return myronAuthenticateDevice(device, nullptr, nullptr);
}

extern "C" __attribute__((noinline)) int
native_verified_block_manifest_sha384(dev_t device, const char *uuid, uint8_t digest[48])
{
  if (!uuid || strlen(uuid) != 36 || !digest) return 0;
  return myronAuthenticateDevice(device, uuid, digest);
}

#include "MyronSystemOS.h"

extern "C" int myron_start_root(void)
{
  unsigned flags = unsigned(myron_ufs_report[1]);
  if (myron_root_start_ready || !(flags & 0x1000) || (myron_ufs_report[2] >> 32)) return 0;
  probeStatus(16, flags, 0);
  unsigned root = 0, probe = 0, log = 0;
  PE_parse_boot_argn("native-ufs-root", &root, sizeof(root));
  PE_parse_boot_argn("native-ufs-probe", &probe, sizeof(probe));
  PE_parse_boot_argn("sheng-log", &log, sizeof(log));
  if (root != 1 || probe || log || storeMode() ||
      !myronRootGeometryValid(myron_root_geometry) ||
      reserveBlocks() != myron_root_geometry.reserveBlocks ||
      strcmp(rootPartitionName(), "unixnu")) {
    probeStatus(16, flags, kIOReturnNotPermitted); return 0;
  }
  IOPlatformExpert *platform = IOService::getPlatform();
  IOService *provider = platform ? platform->getProvider() : nullptr;
  if (!provider || !OSDynamicCast(IOPlatformExpertDevice, provider)) {
    probeStatus(16, flags, kIOReturnUnsupported); return 0;
  }
  NativeUfs *controller = OSTypeAlloc(NativeUfs);
  if (!controller || !controller->init(static_cast<OSDictionary *>(nullptr))) {
    OSSafeReleaseNULL(controller); probeStatus(16, flags, kIOReturnNoMemory); return 0;
  }
  if (!controller->attach(provider)) {
    controller->release(); probeStatus(16, flags, kIOReturnNoResources); return 0;
  }
  if (!controller->start(provider)) {
    controller->detach(provider); controller->release();
    // Preserve the upstream preparation stage so one photo distinguishes
    // allocation, signature, identity and publisher failures.
    myron_ufs_report[16] = native_ufs_root_step;
    myron_ufs_report[17] = gRootDiagnostic.publicationPhase;
    myron_ufs_report[18] = gRootDiagnostic.publicationWindow;
    myron_ufs_report[19] = gRootDiagnostic.verify;
    myron_ufs_report[20] = gRootDiagnostic.windowBytes;
    myron_ufs_report[21] = gRootDiagnostic.prepared;
    probeStatus(16, flags, kIOReturnNotReady); return 0;
  }
  // startRoot prepared and authenticated every window before scheduling its
  // publisher. Keep this controller owned for the lifetime of the boot.
  myron_root_start_ready = 1;
  myron_ufs_report[0] = 98;
  probeStatus(17, flags | 0x2000, 0);
  return 1;
}

// Reached only by instrumentation of the real BSD post-authentication callback.
// This records the result; it never authorizes a root or substitutes an ioctl.
extern "C" void myron_record_root_auth(int apple, int owner)
{
  unsigned flags = unsigned(myron_ufs_report[1]);
  bool pass = owner == 1 && native_owner_root_accepted == 1 &&
      native_owner_root_readonly == 1 &&
      native_owner_root_mount_device == native_owner_root_selected_device &&
      native_owner_root_mount_device != NODEV && myron_root_start_ready &&
      native_ufs_blocks_published >= 2 && native_ufs_verified_blocks &&
      native_ufs_integrity_failures == 0;
  myron_ufs_report[0] = 99;
  myron_ufs_report[16] = uint32_t(apple);
  myron_ufs_report[17] = uint32_t(owner);
  myron_ufs_report[18] = uint32_t(native_owner_root_mount_device);
  myron_ufs_report[19] = uint32_t(native_owner_root_selected_device);
  myron_ufs_report[20] = native_owner_root_readonly;
  myron_ufs_report[21] = native_ufs_blocks_published;
  myron_ufs_report[22] = native_ufs_block_reads;
  myron_ufs_report[23] = native_ufs_verified_blocks;
  myron_ufs_report[24] = native_ufs_integrity_failures;
  probeStatus(18, flags | (pass ? 0x4000 : 0), pass ? 0 : kIOReturnNotPrivileged);
}

// Panic observer: cached software values only. No formatting, allocations,
// MMIO, locks, transport access or recovery attempt is allowed here.
extern "C" int myron_record_root_panic(const void *format, uintptr_t caller)
{
  uint64_t flags = uint32_t(myron_ufs_report[1]);
  if (!(flags & 0x1000)) return 0;
  myron_ufs_report[0] = 100;
  myron_ufs_report[1] = (19ULL << 32) | (flags & ~0x4000ULL);
  myron_ufs_report[2] = (0x67000001ULL << 32) | gRootDiagnostic.result;
  myron_ufs_report[16] = native_ufs_root_step;
  myron_ufs_report[17] = gRootDiagnostic.publicationPhase;
  myron_ufs_report[18] = gRootDiagnostic.publicationWindow;
  myron_ufs_report[19] = gRootDiagnostic.verify;
  myron_ufs_report[20] = gRootDiagnostic.windowBytes;
  myron_ufs_report[21] = gRootDiagnostic.prepared;
  myron_ufs_report[22] = native_ufs_blocks_published;
  myron_ufs_report[23] = vm_page_free_count;
  myron_ufs_report[24] = vm_page_wire_count;
  myron_ufs_report[25] = native_ufs_block_reads;
  myron_ufs_report[26] = native_ufs_verified_blocks;
  myron_ufs_report[27] = native_ufs_integrity_failures;
  myron_ufs_report[28] = reinterpret_cast<uintptr_t>(gRootDiagnostic.stage);
  myron_ufs_report[29] = reinterpret_cast<uintptr_t>(native_ufs_root_failure);
  myron_ufs_report[30] = reinterpret_cast<uintptr_t>(format);
  myron_ufs_report[31] = caller;
  return 1;
}

