def prepared_source(directory):
    source = ARGS.xnu_source.resolve()
    pinned(source, 'ffe7ce0939879d6c6c056ad8ebcee721c159afe4')
    dest = directory / 'bsd/kern/bsd_init.c'
    dest.parent.mkdir(parents=True); shutil.copyfile(source, dest)
    # Apply the actual pinned upstream patches to the actual public XNU source.
    for name in ('offline-owner-root-binding-audit.patch', 'offline-legacy-start.patch'):
        patch = ARGS.upstream.resolve() / 'patches/xnu-12377' / name
        # macOS TMPDIR passes through /var -> /private/var. Git refuses an
        # absolute --directory path through a symlink; relative patch targets
        # from the fixture cwd work on both platforms without --unsafe-paths.
        subprocess.run(['git', 'apply', str(patch)], cwd=directory.resolve(), check=True)
    return dest.read_text()


def prepared_exec_source(directory, manifest=False):
    relative = 'iokit/bsddev/IOKitBSDInit.cpp' if manifest else 'bsd/kern/kern_exec.c'
    source = ((ARGS.iokit_source or ARGS.xnu_source.parents[2] / relative) if manifest else
              ARGS.xnu_source.resolve().with_name('kern_exec.c'))
    pinned(source, '2bbd161eb4c55c5a638f5b4f9341ba62cbfbdf18' if manifest else
           '2467b24045cd8ce0b960723273c495519b2169ae')
    dest = directory / relative
    dest.parent.mkdir(parents=True); shutil.copyfile(source, dest)
    upstream = ARGS.upstream.resolve()
    roots = dict(arch=upstream / 'profiles/arch/arm64e',
                 os=upstream / 'profiles/os/ios-27.0.1-24A446-iphone12-1',
                 device=HERE)
    for scope in ('arch', 'os'):
        series = roots[scope] / 'patches/xnu/series'
        for line in series.read_text().splitlines():
            entry = line.strip()
            if not entry or entry.startswith('#'): continue
            prefix, separator, tail = entry.partition(':')
            patch = (roots[prefix] / tail if separator else series.parent / entry).resolve()
            if '--- a/' + relative not in patch.read_text(): continue
            subprocess.run(['git', 'apply', '--include=' + relative, str(patch)],
                           cwd=directory.resolve(), check=True)
    return dest.read_text()


