// SPDX-License-Identifier: BSD-2-Clause-Patent
// Included in the UFS TU so one controlled constructor registers all classes.
#include "ram-data/NativeRamBlock.cpp"

extern "C" {
extern volatile unsigned myron_storage_registration_state;
volatile unsigned myron_data_start_state = 0;
volatile int myron_data_start_status = 0;
}

extern "C" __attribute__((noinline)) int myron_start_data(void)
{
    // A missing sidecar is not a mounted Data volume. Do not claim readiness.
    if (myron_root_start_ready != 1 || myron_storage_registration_state != 4)
        return -1;
    IORegistryEntry *map = IORegistryEntry::fromPath("/chosen/memory-map", gIODTPlane);
    if (!map) return 0;
    OSObject *dense = map->getProperty("RAMDisk");
    OSObject *packed = map->getProperty("PackedRAMDisk");
    bool supplied = dense || packed;
    OSData *range = OSDynamicCast(OSData, dense ? dense : packed);
    bool valid = supplied && !(dense && packed) && range && range->getLength() == 16;
    map->release();
    if (!supplied) return 0;
    if (!valid) { myron_data_start_status = kIOReturnBadArgument; return -1; }
    if (!__sync_bool_compare_and_swap(&myron_data_start_state, 0U, 1U))
        return myron_data_start_state == 2 ? 1 : -1;
    IOService *provider = IOService::getResourceService();
    NativeRamBlock *disk = nullptr;
    int status = kIOReturnNotReady;
    if (provider) {
        disk = OSTypeAlloc(NativeRamBlock);
        if (!disk || !disk->init(static_cast<OSDictionary *>(nullptr))) {
            status = kIOReturnNoMemory;
        } else if (!disk->attach(provider)) {
            status = kIOReturnNoResources;
        } else if (!disk->start(provider)) {
            disk->detach(provider);
        } else {
            // Keep the successful service owned for this boot. No persistent
            // callbacks are opened by the staged RamBlock implementation.
            myron_data_start_status = 0;
            __sync_synchronize();
            myron_data_start_state = 2;
            return 1;
        }
    }
    OSSafeReleaseNULL(disk);
    myron_data_start_status = status;
    __sync_synchronize();
    myron_data_start_state = 3;
    return -1;
}

