                    self.assertEqual((out/name).read_bytes(), (ARGS.source/name).read_bytes())
            text = (out/'NativeRamBlock.cpp').read_text()
            self.assertIn('unsigned mode = 0;', text)
            self.assertIn('if(logical>0x80000000ULL)return false;', text)
            self.assertNotIn('__attribute__((weak_import))', text)
            with self.assertRaises(ValueError): stage(ARGS.source, out, HERE/'MyronRamData.h')
            with self.assertRaises(ValueError): prepare(text)

