                source = Path(tmp)/'source'; source.mkdir()
                for other in PINS: shutil.copyfile(ARGS.source/other, source/other)
                (source/name).write_bytes((source/name).read_bytes()+b'\n')
                out = Path(tmp)/'out'
                with self.assertRaises(ValueError): stage(source, out, HERE/'MyronRamData.h')
